package com.example.editor.integration.adapter.sirius;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;
import com.example.editor.definition.EditorDefinitionModel;
import com.example.editor.definition.EditorDefinitionTestFixtures;
import com.example.editor.definition.RepresentationDefinition;
import com.example.editor.definition.RepresentationKind;
import com.example.editor.integration.IntegrationArtifactKind;
import com.example.editor.integration.compiler.TechnologyAdapterTestFixtures;
import com.example.editor.integration.compiler.TechnologyCompilationRequest;
import com.example.editor.integration.projection.CanonicalArtifactContent;

class SiriusDesktopTechnologyAdapterTests {
    @Test void exposesExecutableVisualCustomizationBridgeInsideSiriusPlugin(){var result=adapter.compile(TechnologyAdapterTestFixtures.siriusRequest());var paths=result.files().stream().map(file->file.relativePath()).toList();assertThat(paths).anyMatch(v->v.endsWith("HydraVisualFullStack.java")).anyMatch(v->v.endsWith("hydra/visual-editor-definition.json")).anyMatch(v->v.endsWith("hydra/visual-full-stack.json"));var source=result.files().stream().filter(f->f.relativePath().endsWith("HydraVisualFullStack.java")).map(f->new String(f.content(),StandardCharsets.UTF_8)).findFirst().orElseThrow();assertThat(source).contains("resolveNodeAppearance","resolveEdgeAppearance","applyNode","applyEdge","applyNodeAppearance","applyEdgeAppearance","VISUAL_CONDITION_EVALUATION_FAILED");}

    private final SiriusDesktopTechnologyAdapter adapter=new SiriusDesktopTechnologyAdapter(TechnologyAdapterTestFixtures.MAPPER,TechnologyAdapterTestFixtures.ecoreAdapter());
    @Test void targetsSiriusDesktop(){assertThat(adapter.technology().name()).isEqualTo("SIRIUS_DESKTOP");}
    @Test void generatesSeparateEclipsePlugin(){var paths=adapter.compile(TechnologyAdapterTestFixtures.siriusRequest()).files().stream().map(file->file.relativePath()).toList();assertThat(paths).anyMatch(path->path.endsWith("META-INF/MANIFEST.MF")).anyMatch(path->path.endsWith("plugin.xml")).anyMatch(path->path.endsWith("build.properties"));}
    @Test void generatesOdesignWithViewpointMappingsAndTools(){var result=adapter.compile(TechnologyAdapterTestFixtures.siriusRequest());var odesign=result.files().stream().filter(file->file.relativePath().endsWith(".odesign")).findFirst().orElseThrow();assertThat(new String(odesign.content(),StandardCharsets.UTF_8)).contains("ownedViewpoints","DiagramDescription","nodeMappings","edgeMappings","NodeCreationDescription","EdgeCreationDescription");}
    @Test void generatesServiceBoundaries(){var paths=adapter.compile(TechnologyAdapterTestFixtures.siriusRequest()).files().stream().map(file->file.relativePath()).toList();assertThat(paths).anyMatch(path->path.endsWith("HydraSiriusServices.java")).anyMatch(path->path.endsWith("HydraSiriusValidationService.java")).anyMatch(path->path.endsWith("HydraSiriusQuickFixService.java")).anyMatch(path->path.endsWith("HydraSiriusOperationService.java")).anyMatch(path->path.endsWith("HydraSiriusEventBridge.java"));}
    @Test void generatesTransactionalSiriusLifecycle(){var result=adapter.compile(TechnologyAdapterTestFixtures.siriusRequest());var paths=result.files().stream().map(file->file.relativePath()).toList();assertThat(paths).anyMatch(path->path.endsWith("HydraSemanticRuntime.java")).anyMatch(path->path.endsWith("HydraSiriusRuntime.java")).anyMatch(path->path.endsWith("HydraSiriusTransactionLifecycle.java"));String lifecycle=text(result,"HydraSiriusTransactionLifecycle.java");assertThat(lifecycle).contains("transactionAboutToCommit","HydraCommitCommand","SIRIUS_TRANSACTION_COMMIT","restoreOrRebaseline");String runtime=text(result,"HydraSiriusRuntime.java");assertThat(runtime).contains("validateHost","RecordingCommand(domain,\"HYDRA quick fix\")","RecordingCommand(domain,\"HYDRA operation\")");assertThat(text(result,".odesign")).contains("ownedJavaExtensions","service:stableLabel");}
    @Test void generatedSiriusServicesAreExecutableClasses(){var result=adapter.compile(TechnologyAdapterTestFixtures.siriusRequest());assertThat(text(result,"HydraSiriusValidationService.java")).contains("class HydraSiriusValidationService").doesNotContain("interface HydraSiriusValidationService");assertThat(text(result,"HydraSiriusQuickFixService.java")).contains("class HydraSiriusQuickFixService");assertThat(text(result,"HydraSiriusOperationService.java")).contains("class HydraSiriusOperationService");assertThat(text(result,"HydraSiriusEventBridge.java")).contains("class HydraSiriusEventBridge");}
    @Test void targetsCurrentEclipse2026SeptemberRuntime(){var result=adapter.compile(TechnologyAdapterTestFixtures.siriusRequest());assertThat(result.dependencies()).extracting(value->value.version()).contains("7.6.1","2.43.0","2.18.0","1.14.3");assertThat(text(result,"META-INF/MANIFEST.MF")).contains("JavaSE-21","org.eclipse.emf.transaction","org.eclipse.emf.ecore.change");assertThat(text(result,"pom.xml")).contains("<tycho.version>5.0.3</tycho.version>");}
    @Test void includesEcoreProjectionAndCanonicalDocuments(){var paths=adapter.compile(TechnologyAdapterTestFixtures.siriusRequest()).files().stream().map(file->file.relativePath()).toList();assertThat(paths).anyMatch(path->path.endsWith("people.ecore")).anyMatch(path->path.endsWith("hydra/metamodel.json")).anyMatch(path->path.endsWith("hydra/editor_definition.json"));}
    @Test void declaresTychoVerification(){assertThat(adapter.compile(TechnologyAdapterTestFixtures.siriusRequest()).verificationSteps()).singleElement().satisfies(step->assertThat(step.command()).containsExactly("mvn","-q","verify"));}
    @Test void keepsPluginGenerationDeterministic(){var first=adapter.compile(TechnologyAdapterTestFixtures.siriusRequest());var second=adapter.compile(TechnologyAdapterTestFixtures.siriusRequest());assertThat(first.files()).usingRecursiveComparison().isEqualTo(second.files());}
    @Test void honorsConfiguredPluginId(){var source=TechnologyAdapterTestFixtures.siriusRequest();var target=new com.example.editor.integration.IntegrationTarget(source.profile().target().technology(),source.profile().target().kind(),"","host","people-sirius",source.profile().target().buildSystem(),List.of(),List.of(),"",Map.of("pluginId","org.example.people.sirius"));var profile=new com.example.editor.integration.IntegrationProfileModel(source.profile().schemaVersion(),source.profile().id(),source.profile().metamodelId(),source.profile().name(),target,source.profile().deliveryMode(),source.profile().features(),source.profile().artifacts(),source.profile().mappings(),source.profile().injectionPolicy(),source.profile().requiredCapabilities(),source.profile().annotations());var result=adapter.compile(new TechnologyCompilationRequest(profile,source.artifacts(),"test",Map.of()));assertThat(result.metadata()).containsEntry("pluginId","org.example.people.sirius");assertThat(result.files().stream().filter(file->file.relativePath().endsWith("MANIFEST.MF")).map(file->new String(file.content(),StandardCharsets.UTF_8)).findFirst().orElseThrow()).contains("Bundle-SymbolicName: org.example.people.sirius");}
    @Test void warnsForNonDiagramRepresentations(){var source=TechnologyAdapterTestFixtures.siriusRequest();var editor=EditorDefinitionTestFixtures.editor();var table=new RepresentationDefinition("representation:table","Table",RepresentationKind.TABLE,List.of(),List.of(),List.of(),List.of(),true,Map.of());var changed=new EditorDefinitionModel(editor.schemaVersion(),editor.id(),editor.metamodelId(),editor.name(),List.of(editor.representations().getFirst(),table),editor.palette(),editor.forms(),editor.capabilityManifest(),editor.runtimePolicy(),editor.annotations());var artifacts=new ArrayList<>(source.artifacts());artifacts.removeIf(value->value.kind()==IntegrationArtifactKind.EDITOR_DEFINITION);artifacts.add(new CanonicalArtifactContent(IntegrationArtifactKind.EDITOR_DEFINITION,changed.id(),"application/json",TechnologyAdapterTestFixtures.MAPPER.writeValueAsBytes(changed)));var result=adapter.compile(new TechnologyCompilationRequest(source.profile(),artifacts,"test",Map.of()));assertThat(result.diagnostics()).extracting(value->value.code()).contains("SIRIUS_NON_DIAGRAM_VIEWPOINT");}
    @Test void rejectsMissingEditorDefinition(){var source=TechnologyAdapterTestFixtures.siriusRequest();var artifacts=source.artifacts().stream().filter(value->value.kind()!=IntegrationArtifactKind.EDITOR_DEFINITION).toList();assertThatThrownBy(()->adapter.compile(new TechnologyCompilationRequest(source.profile(),artifacts,"test",Map.of()))).hasMessageContaining("EDITOR_DEFINITION");}
    @Test void reportsNotationAsUnsupported(){var source=TechnologyAdapterTestFixtures.siriusRequest();var artifacts=new ArrayList<>(source.artifacts());artifacts.add(new CanonicalArtifactContent(IntegrationArtifactKind.NOTATION,"notation","application/json","{}".getBytes(StandardCharsets.UTF_8)));assertThat(adapter.compile(new TechnologyCompilationRequest(source.profile(),artifacts,"test",Map.of())).diagnostics()).extracting(value->value.code()).contains("UNSUPPORTED_ARTIFACT");}
    @Test void documentsSeparatePluginAndNoGeneratedEmfMutation(){var readme=adapter.compile(TechnologyAdapterTestFixtures.siriusRequest()).files().stream().filter(file->file.relativePath().endsWith("README.md")).findFirst().orElseThrow();assertThat(new String(readme.content(),StandardCharsets.UTF_8)).contains("Separate Eclipse plug-in","does not modify EMF-generated Java classes");}
    @Test void consumesFullTextualStackInsideSiriusPlugin(){var result=adapter.compile(TechnologyAdapterTestFixtures.siriusFullTextualRequest());var paths=result.files().stream().map(file->file.relativePath()).toList();assertThat(paths).anyMatch(v->v.endsWith("HydraTextualFullStack.java")).anyMatch(v->v.endsWith("hydra/textual-editor-customization.json")).anyMatch(v->v.endsWith("hydra/textual-full-stack.json"));var source=result.files().stream().filter(f->f.relativePath().endsWith("HydraTextualFullStack.java")).map(f->new String(f.content(),StandardCharsets.UTF_8)).findFirst().orElseThrow();assertThat(source).contains("VALIDATION=true","QUICK_FIXES=true","EVENTS=true","EVENT_FLOWS=true","GAMIFICATION=true","afterCommit");}

    private String text(com.example.editor.integration.compiler.TechnologyCompilationResult result,String suffix){return result.files().stream().filter(file->file.relativePath().endsWith(suffix)).map(file->new String(file.content(),StandardCharsets.UTF_8)).findFirst().orElseThrow();}
}
